@@ -0,0 +1,22 @@
+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+const read=n=>JSON.parse(readFileSync(new URL(n,import.meta.url),'utf8'));
+const a=read('amendments.json'),b=read('contemporary-register-candidate.json');
+assert.equal(a.as_of,'2026-10-24');
+assert.equal(a.source_coverage.historical_direct_title_search.records,9254);
+assert.equal(a.source_coverage.preserved_months.publications,9275);
+assert.equal(a.selected_title_hits.length,9);
+assert.deepEqual(a.direct_amendments.map(x=>x.publication_id),['2023000445','2026000856']);
+assert.deepEqual(a.direct_amendments.map(x=>x.operative_on_cutoff),[true,false]);
+assert.equal(a.gates.definitive_asof_register,'BLOCKED_EVIDENCE');
+assert.deepEqual([b.upper_units.length,b.councils.length,b.localities.length,b.osm_crosswalk.length],[9,74,162,85]);
+const ids=new Set([...b.upper_units,...b.councils,...b.localities].map(x=>x.id));
+assert.equal(ids.size,245);
+assert.ok(b.councils.every(x=>ids.has(x.parent_id)));
+assert.ok(b.localities.every(x=>!x.parent_id||ids.has(x.parent_id)));
+assert.ok(b.localities.every(x=>x.asof2026_certified===false));
+assert.ok(b.osm_crosswalk.every(x=>x.current_de_facto_parent_certified===false));
+assert.equal(b.current_definitive_register_certified,false);
+assert.equal(a.gates.P9_1_allowed,false);
+assert.equal(b.controls.authorizes_tree_change,false);
+console.log('PASS NI-ADM.1 fail-closed source-scoped; contemporary completeness BLOCKED_EVIDENCE');
